30	/**
31	 * Minimal parameterized query helper — the only approved way to touch the
32	 * in-memory tables. Supports:
33	 *   query('SELECT * FROM <table> WHERE <col> = ?', [value])
34	 *   query('UPDATE <table> SET <col> = ?[, <col> = ?...] WHERE <col> = ?', [values..., whereValue])
35	 * Never interpolate values into `sql` directly — always pass them via `params`.
36	 */
37	export function query(sql: string, params: unknown[] = []): Row[] {
38	  const cursor = { i: 0 };
39	
40	  const select = sql.match(/^SELECT \* FROM (\w+) WHERE (\w+)\s*=\s*(.+)$/i);
41	  if (select) {
42	    const [, table, column, rawValue] = select;
43	    const value = parseValue(rawValue.trim(), params, cursor);
44	    return (tables[table] ?? []).filter(row => row[column] === value);
45	  }
46	
47	  const update = sql.match(/^UPDATE (\w+) SET (.+) WHERE (\w+)\s*=\s*(.+)$/i);
48	  if (update) {
49	    const [, table, setClause, whereColumn, rawWhereValue] = update;
50	    const assignments = setClause.split(',').map(pair => {
51	      const [col, rawVal] = pair.split('=').map(s => s.trim());
52	      return { col, rawVal };
53	    });
54	    const setValues = assignments.map(a => parseValue(a.rawVal, params, cursor));
55	    const whereValue = parseValue(rawWhereValue.trim(), params, cursor);
56	    const rows = (tables[table] ?? []).filter(row => row[whereColumn] === whereValue);
57	    for (const row of rows) {
58	      assignments.forEach((a, i) => {
59	        row[a.col] = setValues[i];
60	      });
61	    }
62	    return rows;
63	  }
64	
65	  throw new Error(`Unsupported query shape: ${sql}`);
66	}

